tructor		virtual ~TColumn();		// Destructor	virtual void ReadFromDisk(TFile* aFile);	virtual void WriteToDisk(TFile* aFile);	virtual void ReadFromScrap(Handle	theScrap,									  long&		scrapOffset);	virtual void WriteToScrap(Handle	theScrap,									 long&	scrapOffset);public:	GridCoordinate fNumber;	FormatRecord fFormat;	FormatRecord fOldFormat;					// save original format for Undo 	ViewCoordinate fWidth;};//--------------------------------------------------------------------------------------------------// TColumnList://--------------------------------------------------------------------------------------------------class TColumnList : public CSortedList_AC{	MA_DECLARE_CLONE;	public:	inline TColumnList() : CSortedList_AC() { }	// Constructor 	virtual ~TColumnList();		// Destructor		virtual CompareResult_AC Compare(const void* item1,										  const void* item2) const;// override 	// Compares columns based on columns number 	virtual TColumn* GetColumn(GridCoordinate c);	// Returns the column whose number is c 	void FreeAll();		// Frees all the columns and then deletes all the elements};//--------------------------------------------------------------------------------------------------// TColumnFormatter: TColumnFormatter is a command object created to change the style or// justification of a column. It is not undoable.//--------------------------------------------------------------------------------------------------class TColumnFormatter : public TCommand{public:	TColumnFormatter(TCalcDocument* itsDocument = NULL,								   CommandNumber itsCommand = cNoCommand);	virtual ~TColumnFormatter();				// override 	virtual void DoIt();				// override 	virtual void UndoIt();			// override 	virtual void RedoIt();			// override protected:	void SaveFormat(const GridCell& aCell);	void SetFormat(const GridCell& aCell);	void RestoreFormat(const GridCell& aCell);public:	TGridViewDesignator		fSelection;						// columns selected for formatting 	TCalcDocument*	fCalcDocument;};//--------------------------------------------------------------------------------------------------// TColumnSizer: TColumnSizer is a command object created to handle mouse movement when// you click on the boundary between two columns.//--------------------------------------------------------------------------------------------------class TColumnSizer : public TTracker{public:	TColumnSizer(TCalcDocument* itsDocument = NULL,									 GridCoordinate	c = 0,									 const CViewPoint& theMouse = gZeroVPt);	virtual ~TColumnSizer();		// Destructor		virtual TTracker* TrackMouse(TrackPhase	/*aTrackPhase*/,										CViewPoint&		/*anchorPoint*/,										CViewPoint&		/*previousPoint*/,										CViewPoint&		nextPoint,										bool		/*mouseDidMove*/);	virtual void TrackFeedback(TrackPhase	/*aTrackPhase*/,									  const CViewPoint&	/*anchorPoint*/ ,									  const CViewPoint&	/*previousPoint*/ ,									  const CViewPoint&	nextPoint,									  bool		mouseDidMove,									  bool		/*turnItOn*/);// override 	virtual void TrackConstrain(TrackPhase		/*aTrackPhase*/,									   const CViewPoint&	/*anchorPoint*/ ,									   const CViewPoint&	/*previousPoint*/ ,									   CViewPoint&			nextPoint,									   bool			/*mouseDidMove*/);// override 	virtual void DoIt();				// override 	virtual void UndoIt();			// override 	virtual void SetColumnWidth(ViewCoordinate newWidth);public:	TCalcDocument*	fCalcDocument;	TCellsView*		fCellsView;	TColumn*		fColumn;	ViewCoordinate			fLeftEdge;	ViewCoordinate			fNewWidth;	ViewCoordinate			fOldWidth;				// remember previous width for Undo  };//--------------------------------------------------------------------------------------------------typedef TemplateIterator_AC<TColumn*> CTColumnIterator;class CCalcColumnIterator : public CTColumnIterator{public:	inline CCalcColumnIterator(TColumnList* theColumnList) :	CTColumnIterator(theColumnList)	{ }	CCalcColumnIterator(TCalcDocument* theCalcDocument);};#endif  //UCALCCOLUMNS/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		04/30/96	Make all constructors use initialization lists if they weren't already							doing do. Switch several more empty constructors to inlines.		04/25/96	More use of CTempxxx classes instead of Failure handling where poss.		04/23/96	Update iterators to be OD stylish.							Pass GridCells as parameters rather than separate coordinates		04/18/96	More Use post-increment with iterators in while loops		----- R10 -----		11/9/95		srf		Remove unnecessary override of TColumnSizer::RedoIt. 		----- 3.3b1 -----		 3/13/95	Change Free methods to destructors. */